package vn.vinhkhang.warehouse;
import java.util.*;import java.math.BigDecimal;import org.springframework.jdbc.core.JdbcTemplate;
final class ShipmentChargers {
 static BigDecimal costPerVehicle(JdbcTemplate db,long shipment){Long doc=document(db,shipment);if(doc==null)return BigDecimal.ZERO;var l=db.queryForList("SELECT quantity,unit_cost FROM stock_document_lines WHERE document_id=?",doc);BigDecimal total=BigDecimal.ZERO;for(var row:l){if(row.get("UNIT_COST")==null)return null;total=total.add(((BigDecimal)row.get("QUANTITY")).multiply((BigDecimal)row.get("UNIT_COST")));}long count=db.queryForObject("SELECT COUNT(*) FROM vehicle_shipment_lines WHERE shipment_id=?",Long.class,shipment);return count==0?BigDecimal.ZERO:total.divide(BigDecimal.valueOf(count),6,java.math.RoundingMode.HALF_UP);}
 static boolean charger(JdbcTemplate db,long id){return db.queryForObject("SELECT p.is_charger OR COALESCE(g.is_charger,FALSE) FROM parts p LEFT JOIN parts g ON g.id=p.color_parent_id WHERE p.id=?",Boolean.class,id);}
 static Long document(JdbcTemplate db,long id){return db.queryForObject("SELECT charger_document_id FROM vehicle_shipments WHERE id=?",Long.class,id);}
 static void guard(JdbcTemplate db,long doc){if(db.queryForObject("SELECT COUNT(*) FROM vehicle_shipments WHERE charger_document_id=?",Integer.class,doc)>0)throw new Api.Problem(409,"Sạc kèm xe: hãy sửa, hủy hoặc khôi phục phiếu xuất xe gốc");}
 static List<Map<String,Object>> lines(JdbcTemplate db,long shipment){Long doc=document(db,shipment);return doc==null?List.of():db.queryForList("SELECT l.part_id,l.quantity,p.name part_name,p.code part_code FROM stock_document_lines l JOIN parts p ON p.id=l.part_id WHERE l.document_id=? ORDER BY l.part_id",doc);}
 static void cancel(Api core,JdbcTemplate db,long shipment){Long doc=document(db,shipment);if(doc==null)return;var h=db.queryForList("SELECT * FROM stock_documents WHERE id=? FOR UPDATE",doc).getFirst();if(Boolean.TRUE.equals(h.get("DELETED")))return;for(var l:db.queryForList("SELECT * FROM stock_document_lines WHERE document_id=? ORDER BY part_id",doc)){long p=((Number)l.get("PART_ID")).longValue();Costing.move(core,db,p,(BigDecimal)l.get("QUANTITY"),doc,null,Costing.sourceCost(db,p,doc,null),true);}db.update("UPDATE stock_documents SET deleted=TRUE WHERE id=?",doc);}
 static void restore(Api core,JdbcTemplate db,long shipment){Long doc=document(db,shipment);if(doc==null)return;for(var l:db.queryForList("SELECT * FROM stock_document_lines WHERE document_id=? ORDER BY part_id",doc)){long p=((Number)l.get("PART_ID")).longValue();core.active("parts",p);Costing.move(core,db,p,((BigDecimal)l.get("QUANTITY")).negate(),doc,null,(BigDecimal)l.get("UNIT_COST"),true);}db.update("UPDATE stock_documents SET deleted=FALSE WHERE id=?",doc);}
 static void persist(Api core,JdbcTemplate db,Api.Session actor,long shipment,Map<String,Object> input){
  if(!input.containsKey("chargers"))return;
  if(!(input.get("chargers") instanceof List<?> raw)||raw.size()>20)throw new Api.Problem(400,"Danh sách sạc không hợp lệ");
  var wanted=new TreeMap<Long,BigDecimal>();for(Object item:raw){if(!(item instanceof Map<?,?>))throw new Api.Problem(400,"Dòng sạc không hợp lệ");@SuppressWarnings("unchecked") var row=(Map<String,Object>)item;long part=core.num(row,"part_id");core.active("parts",part);if(!charger(db,part))throw new Api.Problem(400,"Anh chọn đúng linh kiện sạc");BigDecimal qty=core.dec(row,"quantity");if(qty.stripTrailingZeros().scale()>0||wanted.put(part,qty)!=null)throw new Api.Problem(400,"Số sạc là số nguyên; mỗi loại sạc một dòng");}
  Long doc=document(db,shipment);cancel(core,db,shipment);
  if(wanted.isEmpty()){if(doc!=null)db.update("DELETE FROM stock_document_lines WHERE document_id=?",doc);return;}
  if(doc==null){doc=core.insert("INSERT INTO stock_documents(code,type,location_id,status,note,created_by,posted_at,sales_purpose) VALUES(?,'OUT',1,'POSTED',?,?,CURRENT_TIMESTAMP,'INTERNAL')","SAC-"+shipment+"-"+UUID.randomUUID().toString().substring(0,8),"Sạc thực giao kèm phiếu xuất xe #"+shipment,actor.id());db.update("UPDATE vehicle_shipments SET charger_document_id=? WHERE id=?",doc,shipment);}
  db.update("DELETE FROM stock_document_lines WHERE document_id=?",doc);
  for(var e:wanted.entrySet()){var costs=db.queryForList("SELECT average_unit_cost FROM stock_balances WHERE part_id=? AND location_id=1",e.getKey());BigDecimal cost=costs.isEmpty()?null:(BigDecimal)costs.getFirst().get("AVERAGE_UNIT_COST");db.update("INSERT INTO stock_document_lines(document_id,part_id,quantity,unit_cost) VALUES(?,?,?,?)",doc,e.getKey(),e.getValue(),cost);Costing.move(core,db,e.getKey(),e.getValue().negate(),doc,null,cost,true);}
  db.update("UPDATE stock_documents SET deleted=FALSE WHERE id=?",doc);
 }
}
